def evaluate(s):
    def trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    n = len(s)
    pos = 0

    def skip():
        nonlocal pos
