    def peek():
        skip()
        return s[pos] if pos < n else ""

    def take(ch):
        nonlocal pos
        skip()
        if pos < n and s[pos] == ch:
            pos += 1
        else:
            raise ValueError(f"expected {ch!r}")

    def number():
        nonlocal pos
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if pos == start:
            raise ValueError("expected number")
        return int(s[start:pos])

    def expr():
        value = term()
        while True:
            op = peek()
            if op == "+":
                take("+")
                value += term()
            elif op == "-":
                take("-")
                value -= term()
            else:
                break
        return value

    def term():
        value = factor()
        while True:
            op = peek()
            if op == "*":
                take("*")
                value *= factor()
            elif op == "/":
                take("/")
                value = trunc_div(value, factor())
            else:
                break
        return value

    def factor():
        op = peek()
        if op == "-":
            take("-")
            return -factor()
        if op == "+":
            take("+")
            return factor()
        return primary()

    def primary():
        skip()
        if pos >= n:
            raise ValueError("unexpected end of expression")
        ch = s[pos]
        if ch == "(":
            take("(")
            value = expr()
            take(")")
            return value
        if ch.isdigit():
            return number()
        raise ValueError("unexpected character")

    result = expr()
    skip()
    if pos != n:
        raise ValueError("unexpected trailing characters")
    return result
